    country_data = create_country_data()
    inserted_count = 0
    for qa_pair in country_data:
        try:
            qa_id = db.save_qa_pair(qa_pair)
            print(f'Inserted country QA pair {inserted_count + 1}: {qa_pair.question[:50]}... (ID: {qa_id})')
            inserted_count += 1
        except Exception as e:
            print(f'Error inserting QA pair: {e}')
    
    print(f'\n✅ Successfully inserted {inserted_count} new country QA pairs!')
    all_pairs = db.get_qa_pairs()
    print(f'Total QA pairs in database: {len(all_pairs)}')
